const ICON_GROUPS = {"Navigation":["arrow_forward","arrow_back","arrow_outward","chevron_right","chevron_left","keyboard_arrow_down","menu","close","search","home","open_in_new","language"],"Actions":["add","remove","check","check_circle","download","upload","share","edit","delete","refresh","filter_list","more_horiz","progress_activity"],"Contact":["mail","call","calendar_month","schedule","location_on","chat","forum","send","videocam"],"Statut":["info","warning","error","help","lock","verified_user","notifications"],"Métier":["handshake","groups","person","badge","work","apartment","trending_up","analytics","monitoring","bar_chart","query_stats","campaign","ads_click","rocket_launch","lightbulb","stars","psychology","smart_toy"],"Tech":["database","cloud","cloud_sync","hub","code","api","settings","tune","dashboard","school","workspace_premium"]};

const ANIMS = ['spin', 'pulse', 'bounce', 'nudge', 'shake', 'pop', 'draw'];
const ONCE = { pop: true, draw: true };

const Icon = ({ name, size = 24, animate, trigger = 'always', title, className, style, ...rest }) => {
  const d = ICONS[name];
  if (!d) return null;
  const anim = ANIMS.indexOf(animate) >= 0 ? animate : undefined;
  return (
    <svg viewBox="0 -960 960 960" width={size} height={size} fill="currentColor"
      className={cx('sg-icon', className)} data-anim={anim} data-trigger={anim ? trigger : undefined}
      role={title ? 'img' : undefined} aria-label={title} aria-hidden={title ? undefined : true}
      focusable="false" style={style} {...rest}>
      {title && <title>{title}</title>}
      <path d={d} pathLength="1" />
    </svg>
  );
};

/* SVG autonome animé en SMIL (sans CSS ni JS) : à coller dans une page, un CMS ou à enregistrer en .svg */
const iconMarkup = (name, opts) => {
  const o = Object.assign({ size: 24, color: 'currentColor', animate: null, duration: null, loop: null }, opts || {});
  const d = ICONS[name];
  if (!d) return '';
  const a = o.animate;
  const loop = o.loop == null ? !ONCE[a] : o.loop;
  const rep = loop ? 'repeatCount="indefinite"' : 'repeatCount="1" fill="freeze"';
  const dur = (o.duration || { spin: 1, pulse: 1.6, bounce: 1.2, nudge: 1.2, shake: 0.6, pop: 0.45, draw: 1.4 }[a] || 1) + 's';
  const C = '480 -480';
  const tf = (type, values, extra) => '<animateTransform attributeName="transform" type="' + type + '" values="' + values + '" dur="' + dur + '" ' + rep + (extra || '') + '/>';
  const spline = ' calcMode="spline" keyTimes="0;0.5;1" keySplines="0.4 0 0.2 1;0.4 0 0.2 1"';
  let body = '<path d="' + d + '"/>';
  if (a === 'spin') body = '<g>' + body + '<animateTransform attributeName="transform" type="rotate" from="0 ' + C + '" to="360 ' + C + '" dur="' + dur + '" ' + rep + '/></g>';
  if (a === 'shake') body = '<g>' + body + tf('rotate', '0 ' + C + ';-10 ' + C + ';10 ' + C + ';-6 ' + C + ';0 ' + C) + '</g>';
  if (a === 'bounce') body = '<g>' + body + tf('translate', '0 0;0 -110;0 0', spline) + '</g>';
  if (a === 'nudge') body = '<g>' + body + tf('translate', '0 0;140 0;0 0', spline) + '</g>';
  if (a === 'pulse' || a === 'pop') {
    const v = a === 'pulse' ? '1;1.14;1' : '0.6;1.12;1';
    body = '<g transform="translate(' + C.replace(' ', ' ') + ')"><g>' + tf('scale', v, a === 'pulse' ? spline : '') + '<g transform="translate(-480 480)">' + body + '</g></g></g>';
  }
  if (a === 'draw') body = '<path d="' + d + '" pathLength="1" stroke="' + o.color + '" stroke-width="16" stroke-linejoin="round" stroke-dasharray="1" stroke-dashoffset="1" fill-opacity="0">'
    + '<animate attributeName="stroke-dashoffset" values="1;0" dur="' + dur + '" ' + rep + '/>'
    + '<animate attributeName="fill-opacity" values="0;0;1" keyTimes="0;0.6;1" dur="' + dur + '" ' + rep + '/></path>';
  return '<svg xmlns="http://www.w3.org/2000/svg" width="' + o.size + '" height="' + o.size + '" viewBox="0 -960 960 960" fill="' + o.color + '">' + body + '</svg>';
};


const Arrow = () => <Icon name="arrow_forward" size={18} className="sg-arrow" />;

const Button = ({ variant = 'primary', size = 'md', arrow = false, icon, href, className, children, ...rest }) => {
  const cls = cx('sg-btn', 'sg-btn--' + variant, size === 'lg' && 'sg-btn--lg', className);
  const inner = [icon ? <Icon key="i" name={icon} size={18} /> : null, <span key="l">{children}</span>, arrow ? <Arrow key="a" /> : null];
  return href
    ? <a href={href} className={cls} {...rest}>{inner}</a>
    : <button type="button" className={cls} {...rest}>{inner}</button>;
};

const Tag = ({ tone = 'default', className, children, ...rest }) => (
  <span className={cx('sg-tag', tone !== 'default' && 'sg-tag--' + tone, className)} {...rest}>{children}</span>
);

let sgSeq = 0;
const Input = ({ label, required = false, help, error, multiline = false, disabled = false, id, className, ...rest }) => {
  const auto = React.useMemo(() => 'sg-f-' + (++sgSeq), []);
  const fid = id || auto;
  const Tag_ = multiline ? 'textarea' : 'input';
  const msgId = error || help ? fid + '-msg' : undefined;
  return (
    <div className={cx('sg-field', disabled && 'is-disabled', className)}>
      {label && <label htmlFor={fid} className="sg-field__label">{label}{required && <span className="sg-field__req" aria-hidden="true"> *</span>}</label>}
      <Tag_ id={fid} disabled={disabled} required={required} aria-invalid={error ? true : undefined} aria-describedby={msgId}
        className={cx('sg-field__control', error && 'is-error')} {...rest} />
      {error ? <p id={msgId} className="sg-field__error">{error}</p> : help && <p id={msgId} className="sg-field__help">{help}</p>}
    </div>
  );
};

const SectionHeader = ({ index, overline, title, lead, align = 'start', onDeep = false, className }) => (
  <header className={cx('sg-sh', align === 'center' && 'sg-sh--center', onDeep && 'sg-sh--deep', className)}>
    {index && <span className="sg-sh__index">{index}</span>}
    <div className="sg-sh__body">
      {overline && <p className="sg-overline">{overline}</p>}
      <h2 className="sg-sh__title">{title}</h2>
      {lead && <p className="sg-sh__lead">{lead}</p>}
    </div>
  </header>
);

const ServiceCard = ({ index, title, description, tags = [], href = '#', linkLabel = 'En savoir plus', className }) => (
  <article className={cx('sg-card', className)}>
    <div className="sg-card__top">
      {index && <span className="sg-card__index">{index}</span>}
      {tags.length > 0 && <div className="sg-card__tags">{tags.map(t => <Tag key={t}>{t}</Tag>)}</div>}
    </div>
    <h3 className="sg-card__title">{title}</h3>
    {description && <p className="sg-card__text">{description}</p>}
    <a className="sg-card__link" href={href}>{linkLabel}<Arrow /></a>
  </article>
);

const Logo = ({ logo, alt = 'Solganeo', forceDark = false, className }) => {
  if (!logo) return <span className={cx('sg-wordmark', className)}>Solganeo</span>;
  if (forceDark) return <img className={cx('sg-logo', className)} src={logo.dark} alt={alt} />;
  return (
    <span className={cx('sg-logo-swap', className)}>
      <img className="sg-logo sg-logo--light" src={logo.light} alt={alt} />
      <img className="sg-logo sg-logo--dark" src={logo.dark} alt="" aria-hidden="true" />
    </span>
  );
};

const NavBar = ({ logo, links = ['Expertises', 'Cabinet', 'Carrières', 'Contact'], active, cta = 'Prendre rendez-vous', onCta }) => (
  <nav className="sg-nav" aria-label="Navigation principale">
    <div className="sg-nav__inner">
      <a href="#" className="sg-nav__brand"><Logo logo={logo} /></a>
      <div className="sg-nav__links">
        {links.map(l => <a key={l} href="#" className={cx('sg-nav__link', l === active && 'is-active')} aria-current={l === active ? 'page' : undefined}>{l}</a>)}
      </div>
      {cta && <Button size="md" onClick={onCta}>{cta}</Button>}
    </div>
  </nav>
);

const Hero = ({ overline, title, lead, primary, secondary, tag, logo, aside }) => (
  <section className="sg-hero">
    <div className="sg-hero__inner">
      <div className="sg-hero__main">
        {tag && <Tag tone="signal">{tag}</Tag>}
        {overline && <p className="sg-overline sg-overline--deep">{overline}</p>}
        <h1 className="sg-hero__title">{title}</h1>
        {lead && <p className="sg-hero__lead">{lead}</p>}
        {(primary || secondary) && (
          <div className="sg-hero__ctas">
            {primary && <Button variant="on-deep" size="lg" arrow>{primary}</Button>}
            {secondary && <Button variant="ghost-deep" size="lg">{secondary}</Button>}
          </div>
        )}
      </div>
      {(aside || logo) && (
        <div className="sg-hero__aside">
          {aside || <img className="sg-hero__mark" src={logo.mark} alt="" aria-hidden="true" />}
        </div>
      )}
    </div>
  </section>
);

const Footer = ({ logo, tagline, columns = [], legal = [] }) => (
  <footer className="sg-footer">
    <div className="sg-footer__inner">
      <div className="sg-footer__top">
        <div className="sg-footer__brand">
          <Logo logo={logo} forceDark />
          {tagline && <p className="sg-footer__tagline">{tagline}</p>}
        </div>
        {columns.map(c => (
          <div key={c.title} className="sg-footer__col">
            <p className="sg-overline sg-overline--deep">{c.title}</p>
            <ul>{c.links.map(l => <li key={l}><a href="#">{l}</a></li>)}</ul>
          </div>
        ))}
      </div>
      {legal.length > 0 && (
        <div className="sg-footer__legal">{legal.map((l, i) => <span key={i}>{l}</span>)}</div>
      )}
    </div>
  </footer>
);

globalThis.Solganeo = { Button, Tag, Input, SectionHeader, ServiceCard, NavBar, Hero, Footer, Icon, iconMarkup, icons: Object.keys(ICONS), iconGroups: ICON_GROUPS };
